import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address immutable owner = address(0x123);

    function setUp() public {
        c = new C();
        // The constructor sets owner to msg.sender, which is this contract.
        // We prank as the owner to ensure c.owner() is our known address.
        vm.prank(owner);
        c = new C();
    }

    function testFuzz_property(uint256 amount, address receiver) public {
        // amount must be > 0 for a meaningful transfer
        vm.assume(amount > 0);
        // receiver cannot be the zero address (transfer to zero address reverts)
        vm.assume(receiver != address(0));
        // receiver cannot be the contract itself (transfer to self reverts)
        vm.assume(receiver != address(c));
        // receiver cannot be the owner (in both versions the behavior is the same: sendTo succeeds, but the property focuses on the difference)
        vm.assume(receiver != owner);

        vm.deal(owner, amount);
        vm.prank(owner);

        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference always succeeds (ok == true) when called by the owner.
        // The mutant reverts (ok == false) because msg.sender (owner) != receiver.
        assertTrue(ok);
    }
}

